1	import Foundation
2	
3	/// A logical day. Not a calendar date — the day a body-monitor entry belongs to.
4	///
5	/// Stored as a plain `yyyy-MM-dd` string because it is a label, not an instant:
6	/// arithmetic on it must go through `TimeModel`, which knows the boundary rule.
7	public struct LogicalDay: Codable, Sendable, Hashable, Comparable, CustomStringConvertible {
8	    public let value: String
9	    public init(_ value: String) { self.value = value }
10	    public var description: String { value }
11	    public static func < (a: LogicalDay, b: LogicalDay) -> Bool { a.value < b.value }
12	}
13	
14	/// Where a logical day starts.
15	///
16	/// The Technical Spec defines Almanac's actual rule; that text is unavailable,
17	/// so the rule is **injected rather than assumed**. `.midnight` is a neutral
18	/// placeholder, not a decision. `.wakeOffset` is here because a sleep-tracking
19	/// product almost always needs a boundary in the small hours — an entry at
20	/// 01:30 usually belongs to the night before, not to the new date.
21	public enum DayBoundary: Sendable, Hashable {
22	    case midnight
23	    /// Day starts this many hours after midnight. 4 means 03:59 belongs to the
24	    /// previous logical day and 04:00 starts a new one.
25	    case wakeOffset(hours: Int)
26	
27	    var offsetHours: Int {
28	        switch self {
29	        case .midnight: return 0
30	        case .wakeOffset(let h): return h
31	        }
32	    }
33	}
34	
35	/// Maps instants to logical days in a specific timezone.
36	///
37	/// All conversions go through `Calendar` with an explicit timezone, so DST
38	/// transitions and non-Gregorian display calendars stay the calendar's problem
39	/// rather than becoming arithmetic on 86,400.
40	public struct TimeModel: Sendable {
41	    public let timeZone: TimeZone
42	    public let boundary: DayBoundary
43	    private let calendar: Calendar
44	
45	    public init(timeZone: TimeZone, boundary: DayBoundary = .midnight) {
46	        self.timeZone = timeZone
47	        self.boundary = boundary
48	        var cal = Calendar(identifier: .gregorian)
49	        cal.timeZone = timeZone
50	        self.calendar = cal
51	    }
52	
53	    /// The logical day an instant belongs to.
54	    public func logicalDay(_ instant: Date) -> LogicalDay {
55	        let shifted = instant.addingTimeInterval(-Double(boundary.offsetHours) * 3600)
56	        let parts = calendar.dateComponents([.year, .month, .day], from: shifted)
57	        return LogicalDay(String(format: "%04d-%02d-%02d",
58	                                 parts.year ?? 0, parts.month ?? 0, parts.day ?? 0))
59	    }
60	
61	    /// The instant a logical day begins. Nil only for an unparseable label.
62	    public func start(of day: LogicalDay) -> Date? {
63	        let bits = day.value.split(separator: "-").compactMap { Int($0) }
64	        guard bits.count == 3 else { return nil }
65	        var comps = DateComponents()
66	        comps.year = bits[0]; comps.month = bits[1]; comps.day = bits[2]
67	        comps.hour = boundary.offsetHours
68	        comps.minute = 0; comps.second = 0
69	        comps.timeZone = timeZone
70	        return calendar.date(from: comps)
71	    }
72	
73	    /// The half-open interval [start, end) covering a logical day.
74	    ///
75	    /// Computed by adding one calendar day, not 86,400 seconds — so a DST
76	    /// spring-forward day is 23 hours and a fall-back day is 25, which is what
77	    /// the user actually lived through.
78	    public func bounds(of day: LogicalDay) -> (start: Date, end: Date)? {
79	        guard let start = start(of: day),
80	              let end = calendar.date(byAdding: .day, value: 1, to: start) else { return nil }
81	        return (start, end)
82	    }
83	
84	    public func day(after day: LogicalDay) -> LogicalDay? {
85	        guard let start = start(of: day),
86	              let next = calendar.date(byAdding: .day, value: 1, to: start) else { return nil }
87	        return logicalDay(next)
88	    }
89	
90	    public func contains(_ instant: Date, in day: LogicalDay) -> Bool {
91	        guard let b = bounds(of: day) else { return false }
92	        return instant >= b.start && instant < b.end
93	    }
94	
95	    /// Riyadh: UTC+3, no DST. The project's home timezone.
96	    public static func riyadh(boundary: DayBoundary = .midnight) -> TimeModel {
97	        TimeModel(timeZone: TimeZone(identifier: "Asia/Riyadh") ?? TimeZone(secondsFromGMT: 3 * 3600)!,
98	                  boundary: boundary)
99	    }
100	}
