1	import Foundation
2	
3	/// What to do with an import that carries new content the source did not rank.
4	///
5	/// Unordered changes are held by default. A person can explicitly accept or
6	/// reject them; arrival order does not establish source authority.
7	public enum UnrankedImportPolicy: Sendable, Hashable {
8	    /// Apply it, and mark the stored revision `superseded_unranked` so the
9	    /// assumption is visible in the history rather than implied by its absence.
10	    case applyAndFlag
11	    /// Leave the current version alone and record the incoming one as a
12	    /// conflict for a person to resolve.
13	    case holdAsConflict
14	}
15	
16	/// What a source says about where one version of a report sits in its own
17	/// sequence.
18	///
19	/// This exists because arrival order is not authority. A laboratory's systems
20	/// re-send reports, queues replay, and a nightly job can hand back last week's
21	/// file after this week's correction. Taking "most recently received" as "most
22	/// recent" is how a corrected potassium result quietly reverts.
23	public enum SourceOrdering: Sendable, Hashable {
24	    /// The source said nothing about ordering. Not an error — most PDFs do not
25	    /// carry a version — but it means a differing version cannot be ranked, and
26	    /// the conflict is flagged rather than resolved by guessing.
27	    case unavailable
28	    /// A version or amendment number the source states.
29	    case sequence(Int)
30	    /// An issue or amendment timestamp the source states, as an ISO-8601
31	    /// prefix of any precision.
32	    case issuedAt(String)
33	
34	    var kindText: String? {
35	        switch self {
36	        case .unavailable:  return nil
37	        case .sequence:     return "sequence"
38	        case .issuedAt:     return "issued_at"
39	        }
40	    }
41	
42	    var valueText: String? {
43	        switch self {
44	        case .unavailable:        return nil
45	        case .sequence(let n):    return String(n)
46	        case .issuedAt(let text): return text
47	        }
48	    }
49	
50	    static func from(kind: String?, value: String?) -> SourceOrdering {
51	        guard let kind, let value else { return .unavailable }
52	        switch kind {
53	        case "sequence": return Int(value).map(SourceOrdering.sequence) ?? .unavailable
54	        case "issued_at": return .issuedAt(value)
55	        default: return .unavailable
56	        }
57	    }
58	
59	    /// How this version ranks against one already held.
60	    ///
61	    /// `nil` means the two cannot be ranked at all — either side is
62	    /// `unavailable`, or they use different kinds of marker. A nil answer is
63	    /// the trigger for flagging a conflict, never for picking a winner.
64	    func compare(to other: SourceOrdering) -> ComparisonResult? {
65	        switch (self, other) {
66	        case (.sequence(let a), .sequence(let b)):
67	            return a == b ? .orderedSame : (a < b ? .orderedAscending : .orderedDescending)
68	        case (.issuedAt(let a), .issuedAt(let b)):
69	            guard let l = PartialDateTime(inferringPrecisionFrom: a),
70	                  let r = PartialDateTime(inferringPrecisionFrom: b),
71	                  let left = l.possibleSpan, let right = r.possibleSpan else { return nil }
72	            if l.precision == .instant && r.precision == .instant && l.hasKnownOffset && r.hasKnownOffset {
73	                return left.start == right.start ? .orderedSame : (left.start < right.start ? .orderedAscending : .orderedDescending)
74	            }
75	            if left.end <= right.start { return .orderedAscending }
76	            if right.end <= left.start { return .orderedDescending }
77	            return nil // overlapping uncertainty cannot establish source ordering
78	        default:
79	            return nil
80	        }
81	    }
82	}
