3	/// A reference food as its publisher identifies and names it.
4	public struct NutritionFood: Sendable, Hashable {
5	    public let ref: SourceIdentifier
6	    public let licenceGroup: LicenceGroup
7	    public let foodGroupCode: String
8	    public let foodGroupName: String
9	    /// Where the row came from in the publisher's file, for tracing a value back.
10	    public let sourceRecord: String
11	    /// ISO 639 language code -> name.
12	    public let names: [String: String]
13	    public let primaryName: String
14	}
15	
16	/// Read access to the imported reference foods. A seam over SQL, not an ORM.
17	public struct NutritionCatalog: @unchecked Sendable {
18	    private let db: Database
19	
20	    public init(db: Database) {
21	        self.db = db
22	    }
23	
24	    public func food(_ ref: SourceIdentifier) throws -> NutritionFood? {
25	        guard let row = try db.query("""
26	            SELECT licence_group, food_group_code, food_group_name, source_record
27	            FROM nutrition_food WHERE food_ref = ?;
28	            """, [.text(ref.description)]).first,
29	              let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:)) else { return nil }
30	        var names: [String: String] = [:]
31	        var primary = ""
32	        for name in try db.query("""
33	            SELECT language, name, is_primary FROM nutrition_food_name WHERE food_ref = ? ORDER BY language;
34	            """, [.text(ref.description)]) {
35	            guard let language = name.string("language"), let text = name.string("name") else { continue }
36	            names[language] = text
37	            if name.int("is_primary") == 1 { primary = text }
38	        }
39	        return NutritionFood(ref: ref, licenceGroup: group, foodGroupCode: row.string("food_group_code") ?? "",
40	                             foodGroupName: row.string("food_group_name") ?? "",
41	                             sourceRecord: row.string("source_record") ?? "", names: names, primaryName: primary)
42	    }
43	
44	    /// Every value published for the food on one basis. Tokens keep an empty amount.
45	    public func values(for ref: SourceIdentifier, basis: NutritionBasis) throws -> [NutrientValue] {
46	        try db.query("""
47	            SELECT nutrient_id, amount, qualifier, confidence, source_value, source_nutrient_id, source_unit,
48	                   licence_group
49	            FROM nutrition_value WHERE food_ref = ? AND basis = ? ORDER BY nutrient_id;
50	            """, [.text(ref.description), .text(basis.rawValue)]).compactMap { row in
51	            // The table's CHECK constraints admit only values these types can parse.
52	            guard let nutrient = row.string("nutrient_id"),
53	                  let qualifier = row.string("qualifier").flatMap(NutrientQualifier.init(rawValue:)),
54	                  let group = row.string("licence_group").flatMap(LicenceGroup.init(rawValue:)),
55	                  let sourceValue = row.string("source_value"),
56	                  let sourceNutrient = row.string("source_nutrient_id"),
57	                  let sourceUnit = row.string("source_unit") else { return nil }
58	            return NutrientValue(foodRef: ref, nutrientID: nutrient, amount: row.double("amount"),
59	                                 qualifier: qualifier, confidence: row.string("confidence"),
60	                                 sourceValue: sourceValue, sourceNutrientID: sourceNutrient,
61	                                 sourceUnit: sourceUnit, licenceGroup: group, basis: basis)
62	        }
63	    }
64	
65	    /// The bases the publisher gives values on: per 100 g, and for some liquids per 100 mL too.
66	    public func bases(for ref: SourceIdentifier) throws -> [NutritionBasis] {
67	        try db.query("SELECT DISTINCT basis FROM nutrition_value WHERE food_ref = ? ORDER BY basis;",
68	                     [.text(ref.description)])
69	            .compactMap { $0.string("basis").flatMap(NutritionBasis.init(rawValue:)) }
70	    }
71	
72	    /// Almanac's calorie number for the food on one basis (see `EnergyEstimate.preferred`).
73	    public func energy(for ref: SourceIdentifier, basis: NutritionBasis) throws -> EnergyEstimate? {
74	        EnergyEstimate.preferred(from: try values(for: ref, basis: basis), basis: basis)
75	    }
76	
77	    /// Foods whose name in any language contains `text`, compared folded (`TextFold`):
78	    /// case, accents and Arabic letter variants do not matter. Each food once, by primary name.
79	    public func search(_ text: String, limit: Int = 50) throws -> [NutritionFood] {
80	        let folded = TextFold.fold(text)
81	        guard !folded.isEmpty, limit > 0 else { return [] }
82	        let pattern = "%" + folded.replacingOccurrences(of: "\\", with: "\\\\")
83	            .replacingOccurrences(of: "%", with: "\\%")
84	            .replacingOccurrences(of: "_", with: "\\_") + "%"
85	        return try db.query("""
86	            SELECT f.food_ref FROM nutrition_food f
87	            JOIN nutrition_food_name p ON p.food_ref = f.food_ref AND p.is_primary = 1
88	            WHERE EXISTS (SELECT 1 FROM nutrition_food_name n
89	                          WHERE n.food_ref = f.food_ref AND n.name_fold LIKE ? ESCAPE '\\')
90	            ORDER BY p.name_fold, f.food_ref
91	            LIMIT ?;
92	            """, [.text(pattern), .integer(Int64(limit))])
93	            .compactMap { row in
94	                try row.string("food_ref").flatMap(SourceIdentifier.init(parsing:)).flatMap(food)
95	            }
96	    }
97	}
