3	public struct NutritionImportReport: Sendable, Hashable {
4	    public let bundleSHA256: String
5	    public let schemaVersion: Int
6	    public let namespaces: [SourceIdentifier.Namespace]
7	    public let foodCount: Int
8	    public let valueCount: Int
9	}
10	
11	public enum NutritionImportError: Error, CustomStringConvertible, Sendable {
12	    case bundleMissing(path: String)
13	    case unsupportedSchemaVersion(found: String?)
14	    case unknownNamespace(String)
15	    case unknownLicenceGroup(identifier: String, group: String)
16	    case licenceGroupDisagrees(identifier: String, bundle: LicenceGroup, registry: LicenceGroup)
17	    case qualifierVocabularyDiffers(String)
18	
19	    public var description: String {
20	        switch self {
21	        case .bundleMissing(let path):
22	            return "No nutrition bundle at \(path)."
23	        case .unsupportedSchemaVersion(let found):
24	            return "Nutrition bundle schema version \(found ?? "(none)") is not supported; this build reads "
25	                + "version \(NutritionReferenceImporter.supportedSchemaVersion)."
26	        case .unknownNamespace(let namespace):
27	            return "Nutrition bundle names source namespace \"\(namespace)\", which AlmanacCore does not know."
28	        case .unknownLicenceGroup(let identifier, let group):
29	            return "\(identifier) has licence group \"\(group)\", which AlmanacCore does not know."
30	        case .licenceGroupDisagrees(let identifier, let bundle, let registry):
31	            return "\(identifier) is labelled licence group \(bundle.rawValue) but its source is group "
32	                + "\(registry.rawValue). The bundle was not built by tools/nutrition."
33	        case .qualifierVocabularyDiffers(let qualifier):
34	            return "The bundle's qualifier \"\(qualifier)\" does not mean what NutrientQualifier means."
35	        }
36	    }
37	}
38	
39	/// Replaces the nutrition reference tables with a bundle built by tools/nutrition
40	/// (bundle schema v1). Nothing is written to the bundle. Everything it claims is
41	/// checked first — the licence assertion runs again here, against AlmanacCore's own
42	/// registry — and then every row is copied in one transaction, so a refused or
43	/// failed import leaves the previous reference data exactly as it was.
44	public struct NutritionReferenceImporter: @unchecked Sendable {
45	    public static let supportedSchemaVersion = 1
46	    private let db: Database
47	    private let clock: any Clock
48	
49	    public init(db: Database, clock: any Clock = SystemClock()) {
50	        self.db = db
51	        self.clock = clock
52	    }
53	
54	    @discardableResult
55	    public func importBundle(at path: String) throws -> NutritionImportReport {
56	        // ATTACH would create an empty database at a missing path and import nothing.
57	        guard FileManager.default.fileExists(atPath: path) else {
58	            throw NutritionImportError.bundleMissing(path: path)
59	        }
60	        let sha256 = try SHA256File.hex(ofFileAt: path)
61	        try db.run("ATTACH DATABASE ? AS bundle;", [.text(path)])
62	        defer { try? db.execute("DETACH DATABASE bundle;") }
63	
64	        let version = try meta("schema_version")
65	        guard version == String(Self.supportedSchemaVersion) else {
66	            throw NutritionImportError.unsupportedSchemaVersion(found: version)
67	        }
68	        try verifyQualifiers()
69	        try verifyLicenceGroups("""
70	            SELECT namespace AS identifier, namespace, licence_group FROM bundle.nutrition_source;
71	            """)
72	        try verifyLicenceGroups("""
73	            SELECT food_ref AS identifier, namespace, licence_group FROM bundle.nutrition_food;
74	            """)
75	        try verifyLicenceGroups("""
76	            SELECT food_ref || '/' || nutrient_id || '/' || basis AS identifier,
77	                   substr(food_ref, 1, instr(food_ref, ':') - 1) AS namespace, licence_group
78	            FROM bundle.nutrition_value;
79	            """)
80	        let namespaces = try db.query("SELECT namespace FROM bundle.nutrition_source ORDER BY namespace;")
81	            .compactMap { $0.string("namespace").flatMap(SourceIdentifier.Namespace.init(rawValue:)) }
82	        // Bound, not interpolated: `Namespace` is a closed enum, but this still
83	        // reads as data rather than as something safe to string-paste.
84	        let namespacePlaceholders = namespaces.map { _ in "?" }.joined(separator: ", ")
85	        let namespaceValues: [SQLValue] = namespaces.map { .text($0.rawValue) }
86	
87	        return try db.transaction {
88	            // Scoped to the namespaces this bundle actually carries. A blanket
89	            // `DELETE FROM nutrition_food` would also erase `almanac:` rows —
90	            // dishes a person authored on this device — on every reimport,
91	            // because the pipeline bundle never ships them; scoping the delete
92	            // to the bundle's own namespaces is what lets rows this import does
93	            // not claim to know about survive it.
94	            try db.run("""
95	                DELETE FROM nutrition_value WHERE food_ref IN (
96	                    SELECT food_ref FROM nutrition_food WHERE namespace IN (\(namespacePlaceholders))
97	                );
98	                """, namespaceValues)
99	            try db.run("""
100	                DELETE FROM nutrition_food_name WHERE food_ref IN (
101	                    SELECT food_ref FROM nutrition_food WHERE namespace IN (\(namespacePlaceholders))
102	                );
103	                """, namespaceValues)
104	            try db.run("DELETE FROM nutrition_food WHERE namespace IN (\(namespacePlaceholders));",
105	                       namespaceValues)
106	            try db.execute("""
107	            DELETE FROM nutrition_nutrient;
108	            DELETE FROM nutrition_source;
109	            INSERT INTO nutrition_source (namespace, dataset_id, name, release, licence, licence_group,
110	                                          attribution, url)
