43	/// A thin, non-generic wrapper over the SQLite C API.
44	///
45	/// Deliberately small. It is a seam, not an ORM: the schema lives in
46	/// migrations, and everything above this type works in plain SQL so that a
47	/// migration and a query read the same on Linux and on iOS.
48	/// Thread safety: the connection is opened with SQLITE_OPEN_FULLMUTEX, so
49	/// SQLite itself serialises concurrent use of the handle. That is what makes
50	/// the `@unchecked Sendable` claim true rather than convenient.
51	public final class Database: @unchecked Sendable {
52	    private var handle: OpaquePointer?
53	    /// Internal escape hatch for C APIs that need the raw connection.
54	    var rawHandle: OpaquePointer? { handle }
55	    public let path: String
56	    /// Held for the whole of `transaction`. Recursive, so the same thread can
57	    /// nest; another thread waits rather than joining the open transaction.
58	    private let transactionLock = NSRecursiveLock()
59	
60	    public init(path: String) throws {
61	        self.path = path
62	        var h: OpaquePointer?
63	        let flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX
64	        let rc = sqlite3_open_v2(path, &h, flags, nil)
65	        guard rc == SQLITE_OK, let opened = h else {
66	            let err = SQLiteError.from(h, code: rc)
67	            if h != nil { sqlite3_close_v2(h) }
68	            throw err
69	        }
70	        self.handle = opened
71	        try execute("PRAGMA foreign_keys = ON;")
72	        try execute("PRAGMA journal_mode = WAL;")
73	        try execute("PRAGMA busy_timeout = 5000;")
74	    }
75	
76	    public static func inMemory() throws -> Database { try Database(path: ":memory:") }
77	
78	    deinit { if let handle { sqlite3_close_v2(handle) } }
79	
80	    /// Runs one or more statements with no parameters and no result rows.
81	    public func execute(_ sql: String) throws {
82	        var errmsg: UnsafeMutablePointer<CChar>?
83	        let rc = sqlite3_exec(handle, sql, nil, nil, &errmsg)
84	        if rc != SQLITE_OK {
85	            let message = errmsg.map { String(cString: $0) } ?? "unknown sqlite error"
86	            if let errmsg { sqlite3_free(errmsg) }
87	            throw SQLiteError(code: rc, message: message, sql: sql)
88	        }
89	    }
90	
91	    @discardableResult
92	    public func run(_ sql: String, _ parameters: [SQLValue] = []) throws -> Int {
93	        let stmt = try prepare(sql, parameters)
94	        defer { sqlite3_finalize(stmt) }
95	        let rc = sqlite3_step(stmt)
96	        guard rc == SQLITE_DONE || rc == SQLITE_ROW else {
97	            throw SQLiteError.from(handle, code: rc, sql: sql)
98	        }
99	        return Int(sqlite3_changes(handle))
100	    }
101	
102	    public func query(_ sql: String, _ parameters: [SQLValue] = []) throws -> [Row] {
103	        let stmt = try prepare(sql, parameters)
104	        defer { sqlite3_finalize(stmt) }
105	
106	        let columnCount = Int(sqlite3_column_count(stmt))
107	        var names: [String] = []
108	        names.reserveCapacity(columnCount)
109	        for i in 0..<columnCount {
110	            names.append(String(cString: sqlite3_column_name(stmt, Int32(i))))
111	        }
112	
113	        var rows: [Row] = []
114	        while true {
115	            let rc = sqlite3_step(stmt)
116	            if rc == SQLITE_DONE { break }
117	            guard rc == SQLITE_ROW else { throw SQLiteError.from(handle, code: rc, sql: sql) }
118	            var values: [String: SQLValue] = [:]
119	            for i in 0..<columnCount {
120	                values[names[i]] = columnValue(stmt, Int32(i))
121	            }
122	            rows.append(Row(values))
123	        }
124	        return rows
125	    }
126	
127	    private func columnValue(_ stmt: OpaquePointer?, _ index: Int32) -> SQLValue {
128	        switch sqlite3_column_type(stmt, index) {
129	        case SQLITE_INTEGER: return .integer(sqlite3_column_int64(stmt, index))
130	        case SQLITE_FLOAT:   return .real(sqlite3_column_double(stmt, index))
131	        case SQLITE_TEXT:
132	            guard let c = sqlite3_column_text(stmt, index) else { return .null }
133	            return .text(String(cString: c))
134	        case SQLITE_BLOB:
135	            let n = Int(sqlite3_column_bytes(stmt, index))
136	            guard n > 0, let p = sqlite3_column_blob(stmt, index) else { return .blob([]) }
137	            let buf = UnsafeRawBufferPointer(start: p, count: n)
138	            return .blob(Array(buf))
139	        default: return .null
140	        }
141	    }
142	
143	    private func prepare(_ sql: String, _ parameters: [SQLValue]) throws -> OpaquePointer? {
144	        var stmt: OpaquePointer?
145	        let rc = sqlite3_prepare_v2(handle, sql, -1, &stmt, nil)
146	        guard rc == SQLITE_OK else { throw SQLiteError.from(handle, code: rc, sql: sql) }
147	        for (offset, value) in parameters.enumerated() {
148	            let i = Int32(offset + 1)
149	            let brc: Int32
150	            switch value {
151	            case .null:            brc = sqlite3_bind_null(stmt, i)
152	            case .integer(let v):  brc = sqlite3_bind_int64(stmt, i, v)
153	            case .real(let v):     brc = sqlite3_bind_double(stmt, i, v)
154	            case .text(let v):     brc = sqlite3_bind_text(stmt, i, v, -1, SQLITE_TRANSIENT)
155	            case .blob(let bytes):
156	                brc = bytes.isEmpty
157	                    ? sqlite3_bind_zeroblob(stmt, i, 0)
158	                    : bytes.withUnsafeBufferPointer {
159	                        sqlite3_bind_blob(stmt, i, $0.baseAddress, Int32(bytes.count), SQLITE_TRANSIENT)
160	                      }
161	            }
162	            guard brc == SQLITE_OK else {
163	                sqlite3_finalize(stmt)
164	                throw SQLiteError.from(handle, code: brc, sql: sql)
165	            }
166	        }
167	        return stmt
168	    }
169	
170	    /// Runs `body` inside a transaction, rolling back on any thrown error.
171	    ///
172	    /// **Nests.** `BEGIN` inside an open transaction is an error in SQLite, so
173	    /// a call made while one is already running uses a SAVEPOINT instead: the
174	    /// inner scope rolls back on its own without discarding the outer one, and
175	    /// nothing commits until the outermost scope does. That is what lets a
176	    /// store compose two writes that each own their own consistency — a recipe
177	    /// and the values derived from it, or a whole source's rows — without
178	    /// either having to know whether it is the outer call.
179	    ///
180	    /// Whether a transaction is open is asked of SQLite rather than tracked
181	    /// here, so there is no Swift-side counter that can drift out of step with
182	    /// the connection. Savepoints of the same name are last-in-first-out, which
183	    /// is exactly how these scopes close.
184	    ///
185	    /// **Nesting is per thread, which the lock is what makes true.** SQLite
186	    /// reports an open transaction for the *connection*, not for the caller, so
187	    /// without the lock a second thread arriving mid-transaction would read
188	    /// "already open" and quietly attach its savepoint to work it has nothing
189	    /// to do with — two unrelated units of work committing or rolling back
190	    /// together. `SQLITE_OPEN_FULLMUTEX` serialises statements, not the spans
191	    /// between them, so it does not cover this. Holding the lock for the whole
192	    /// scope means another thread waits and then gets a genuine outer
193	    /// transaction of its own.
194	    public func transaction<T>(_ body: () throws -> T) throws -> T {
195	        transactionLock.lock()
196	        defer { transactionLock.unlock() }
197	        guard sqlite3_get_autocommit(handle) != 0 else { return try savepoint(body) }
198	        try execute("BEGIN IMMEDIATE;")
199	        do {
200	            let result = try body()
201	            try execute("COMMIT;")
202	            return result
203	        } catch {
204	            try? execute("ROLLBACK;")
205	            throw error
206	        }
207	    }
208	
209	    private func savepoint<T>(_ body: () throws -> T) throws -> T {
210	        try execute("SAVEPOINT almanac_nested;")
211	        do {
212	            let result = try body()
213	            try execute("RELEASE almanac_nested;")
214	            return result
215	        } catch {
216	            // Rolling back to a savepoint does not release it, so both
217	            // statements are needed to leave the enclosing scope as it was.
218	            try? execute("ROLLBACK TO almanac_nested;")
219	            try? execute("RELEASE almanac_nested;")
220	            throw error
221	        }
222	    }
223	
224	    public var userVersion: Int {
225	        get { (try? query("PRAGMA user_version;").first?.int("user_version")).flatMap { $0 }.map(Int.init) ?? 0 }
226	    }
227	}
