38	        let digest = SHA256File.hex(of: bytes)
39	        let suffix = (preferredName as NSString).pathExtension
40	        let name = suffix.isEmpty ? digest : "\(digest).\(suffix)"
41	        let relative = "\(digest.prefix(2))/\(name)"
42	        let target = root.appendingPathComponent(relative)
43	        try FileManager.default.createDirectory(at: target.deletingLastPathComponent(),
44	                                                withIntermediateDirectories: true)
45	        if !FileManager.default.fileExists(atPath: target.path) {
46	            try Data(bytes).write(to: target)
47	        }
48	        return StoredDocument(relativePath: relative, byteCount: bytes.count, sha256: digest)
49	    }
