4	/// Skeleton backup/restore.
5	///
6	/// Uses SQLite's online backup API rather than copying the file, because a WAL
7	/// database on disk is not a consistent snapshot — copying it while the app is
8	/// running produces a backup that restores to a moment that never existed.
9	public struct BackupService: Sendable {
10	    private let db: Database
11	    private let clock: any Clock
12	
13	    public init(db: Database, clock: any Clock = SystemClock()) {
14	        self.db = db
15	        self.clock = clock
16	    }
17	
18	    public enum BackupError: Error, CustomStringConvertible, Sendable {
19	        case cannotOpenDestination(String)
20	        case backupFailed(Int32)
21	        case restoreNotImplemented
22	
23	        public var description: String {
24	            switch self {
25	            case .cannotOpenDestination(let p): return "Could not open backup destination at \(p)"
26	            case .backupFailed(let c): return "SQLite backup failed with code \(c)"
27	            case .restoreNotImplemented:
28	                return "Restore is deliberately unimplemented until the spec's restore semantics are available."
29	            }
30	        }
31	    }
32	
33	    /// Writes a consistent snapshot to `path` and records it in `backup_manifest`.
34	    @discardableResult
35	    public func snapshot(to path: String, note: String? = nil) throws -> Int64 {
36	        let destination = try Database(path: path)
37	        try db.backup(into: destination)
38	
39	        let attrs = try FileManager.default.attributesOfItem(atPath: path)
40	        let bytes = (attrs[.size] as? NSNumber)?.int64Value ?? 0
41	        let digest = try SHA256File.hex(ofFileAt: path)
42	        let version = try currentSchemaVersion()
43	
44	        try db.run("""
45	        INSERT INTO backup_manifest (created_at, schema_version, byte_count, sha256, note)
46	        VALUES (?, ?, ?, ?, ?);
47	        """, [
48	            .text(ISO8601DateFormatter().string(from: clock.now)),
49	            .integer(Int64(version)),
50	            .integer(bytes),
51	            .text(digest),
52	            note.map { SQLValue.text($0) } ?? .null
53	        ])
54	        return bytes
55	    }
56	
57	    private func currentSchemaVersion() throws -> Int {
58	        let rows = try db.query("SELECT COALESCE(MAX(version), 0) AS v FROM schema_migrations;")
59	        return Int(rows.first?.int("v") ?? 0)
60	    }
61	
62	    /// Restore is intentionally not implemented. The spec defines what happens
63	    /// to in-flight sync anchors and to user rows created after the snapshot;
64	    /// guessing that is how a restore silently loses a day of logs.
65	    public func restore(from path: String) throws -> Never {
66	        throw BackupError.restoreNotImplemented
67	    }
68	}
