70	extension Database {
71	    /// SQLite online backup API — a consistent copy even under WAL.
72	    func backup(into destination: Database) throws {
73	        try withHandles(destination) { src, dst in
74	            guard let b = sqlite3_backup_init(dst, "main", src, "main") else {
75	                throw BackupService.BackupError.backupFailed(sqlite3_errcode(dst))
76	            }
77	            sqlite3_backup_step(b, -1)
78	            let rc = sqlite3_backup_finish(b)
79	            guard rc == SQLITE_OK else { throw BackupService.BackupError.backupFailed(rc) }
80	        }
81	    }
82	}
