3	/// Merges module-provided entries into one ordered sequence.
4	///
5	/// Holds no state and stores nothing. Ordering is a total order over fields
6	/// every entry carries, so the result does not depend on provider order or on
7	/// the order rows came back from SQLite.
8	public struct Timeline: Sendable {
9	    private let providers: [any TimelineProviding]
10	
11	    public init(providers: [any TimelineProviding]) {
12	        self.providers = providers
13	    }
14	
15	    public func entries(from: String, to: String) throws -> [TimelineEntry] {
16	        var merged: [TimelineEntry] = []
17	        for provider in providers {
18	            merged.append(contentsOf: try provider.entries(from: from, to: to))
19	        }
20	        return merged.sorted(by: Timeline.precedes)
21	    }
22	
23	    // There is deliberately no `undatedEntries`. Every module resolves a
24	    // placement — occurrence, else reported, else recorded — so no entry
25	    // currently reaches the timeline with an unknown time, and an accessor
26	    // that could only ever return an empty array would imply a bucket that
27	    // does not exist. `TimelineEntry.basis` is what distinguishes a weak
28	    // placement from a real occurrence.
29	
30	    static func precedes(_ a: TimelineEntry, _ b: TimelineEntry) -> Bool {
31	        if a.occurrence != b.occurrence { return a.occurrence < b.occurrence }
32	        if a.domain != b.domain { return a.domain < b.domain }
33	        if a.kind != b.kind { return a.kind < b.kind }
34	        if a.recordTable != b.recordTable { return a.recordTable < b.recordTable }
35	        return a.recordID < b.recordID
36	    }
37	}
